import React from "react";
import {argTypes as plotArgTypes} from "./Plot.args.jsx";
import {assign} from "@d3plus/dom";

import {Scatter as D3plusScatter} from "@d3plus/react";
export const Scatter = ({config}) => <D3plusScatter config={config} />;

export const argTypes = assign(
  /**
   * Filters out unused argTypes from the Plot primitive and
   * overrides any defaults that have been changed in Scatter
   */
  Object.keys(plotArgTypes)
    .filter(k => !k.match(/^(shape)$/))
    .reduce((obj, k) => ((obj[k] = plotArgTypes[k]), obj), {}),

  /**
   * Scatter-specific methods
   */

  {},
);
